package com.onebytelabs.zlplay;
import android.app.*;import android.content.*;import android.os.*;import android.view.*;import android.widget.*;import com.onebytelabs.zlplay.project.*;import java.lang.reflect.*;import java.util.concurrent.atomic.*;

/** Settings, support action, effective card key and camera rotation without saving camera images. */
public final class QueueFinalSmoke {
 private static Object get(Object o,String n)throws Exception{Field f=o.getClass().getDeclaredField(n);f.setAccessible(true);return f.get(o);}
 private static void set(Object o,String n,Object value)throws Exception{Field f=o.getClass().getDeclaredField(n);f.setAccessible(true);f.set(o,value);}
 private static void call(Instrumentation test,Object o,String n,Class<?>[] types,Object... args)throws Exception{Method method=o.getClass().getDeclaredMethod(n,types);method.setAccessible(true);test.runOnMainSync(()->{try{method.invoke(o,args);}catch(Exception e){throw new RuntimeException(e);}});}
 private static Button find(View v,String desc){if(v instanceof Button&&desc.contentEquals(v.getContentDescription()==null?"":v.getContentDescription()))return(Button)v;if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++){Button found=find(((ViewGroup)v).getChildAt(i),desc);if(found!=null)return found;}return null;}
 public static Bundle run(Instrumentation test)throws Exception{
  MainActivity main=(MainActivity)test.startActivitySync(new Intent(test.getTargetContext(),MainActivity.class).putExtra("com.onebytelabs.zlplay.SKIP_RESTORE_TEST",true).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));Activity camera=null;
  try{
   call(test,main,"showSettings",new Class[]{int.class},0);Dialog before=(Dialog)get(main,"settingsDialog");call(test,main,"showSettings",new Class[]{int.class},3);if(before!=get(main,"settingsDialog"))throw new AssertionError("Remote setup must reuse settings");
   View body=before.findViewById(android.R.id.content);if(find(body,main.getString(R.string.remote_scan))==null||find(body,main.getString(R.string.player_mode))!=null)throw new AssertionError("Remote setup actions");test.runOnMainSync(before::dismiss);
   SetlistSpec setlist=new SetlistSpec();setlist.title="Synthetic";SetlistSpec.Song song=new SetlistSpec.Song();song.name="Song - Artist";song.originalKey="D";song.tonalKey="G#";song.project="Song.rpp";song.folder="Song";setlist.songs.add(song);set(main,"setlist",setlist);set(main,"setlistIndex",-1);call(test,main,"renderSetlist",new Class[]{});LinearLayout cards=(LinearLayout)get(main,"songCards");if(((Button)cards.getChildAt(0)).getCompoundDrawables()[2]==null)throw new AssertionError("Key badge missing");Method key=MainActivity.class.getDeclaredMethod("songEffectiveKey",SetlistSpec.Song.class,int.class);key.setAccessible(true);if(!"Ab".equals(key.invoke(main,song,0)))throw new AssertionError("Original key displayed instead of destination");
   AtomicReference<String> url=new AtomicReference<>();Instrumentation.ActivityMonitor external=new Instrumentation.ActivityMonitor(){@Override public Instrumentation.ActivityResult onStartActivity(Intent intent){if(Intent.ACTION_VIEW.equals(intent.getAction())){url.set(intent.getDataString());return new Instrumentation.ActivityResult(Activity.RESULT_CANCELED,null);}return null;}};test.addMonitor(external);call(test,main,"showLicenses",new Class[]{});Dialog about=(Dialog)get(main,"aboutDialog");Button support=find(about.findViewById(android.R.id.content),main.getString(R.string.support_project));if(support==null)throw new AssertionError("Support action missing");test.runOnMainSync(support::performClick);test.removeMonitor(external);if(!"https://livepix.gg/1bytelabs".equals(url.get()))throw new AssertionError("Wrong support link");test.runOnMainSync(about::dismiss);
   camera=test.startActivitySync(new Intent(test.getTargetContext(),QrScanActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));final Activity scanner=camera;int[] previews=new int[2];for(int i=0;i<2;i++){final int orientation=i==0?android.content.pm.ActivityInfo.SCREEN_ORIENTATION_LANDSCAPE:android.content.pm.ActivityInfo.SCREEN_ORIENTATION_REVERSE_LANDSCAPE;test.runOnMainSync(()->scanner.setRequestedOrientation(orientation));Thread.sleep(850);for(int spin=0;spin<40;spin++){Thread.sleep(100);if(get(scanner,"camera")!=null&&(Integer)get(scanner,"lastRotation")==scanner.getWindowManager().getDefaultDisplay().getRotation())break;}if(get(scanner,"camera")==null)throw new AssertionError("Camera not open");previews[i]=(Integer)get(scanner,"previewRotation");}if((previews[0]+180)%360!=previews[1])throw new AssertionError("Reverse-landscape camera rotation: "+previews[0]+" / "+previews[1]+" display="+scanner.getWindowManager().getDefaultDisplay().getRotation());
   Bundle result=new Bundle();result.putString("status","PASS: integrated remote setup, destination-key badge, support link and both landscape camera rotations");result.putString("cameraAngles",previews[0]+" / "+previews[1]);return result;
  }finally{if(camera!=null){Activity scanner=camera;test.runOnMainSync(scanner::finish);}test.runOnMainSync(main::finish);}
 }
}
